//! Snapshot of omp's model catalog for the providers mu drives natively: context windows, limits,
//! prices, reasoning ladders and Chat Completions quirks. Regenerated by
//! `scripts/maint/gen-catalog.sh` on every omp bump; parsed on first use.

use mu_base::models::{AnthropicQuirks, Api, CompletionsCompat, ModelSpec, ThinkingMode, ThinkingSpec};
use serde::Deserialize;
use std::collections::HashMap;
use std::sync::OnceLock;

const SNAPSHOT: &str = include_str!("catalog.json");

#[derive(Debug, Clone, Copy, Default, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", default)]
pub struct LongContext {
    pub input_threshold: f64,
    pub input: f64,
    pub output: f64,
    pub cache_read: f64,
    pub cache_write: f64,
}

#[derive(Debug, Clone, Copy, Default, Deserialize, PartialEq)]
#[serde(rename_all = "camelCase", default)]
pub struct Cost {
    pub input: f64,
    pub output: f64,
    pub cache_read: f64,
    pub cache_write: f64,
    pub long_context: Option<LongContext>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct ThinkingRow {
    pub mode: String,
    #[serde(default)]
    pub efforts: Vec<String>,
    pub supports_display: Option<bool>,
}

#[derive(Debug, Clone, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Row {
    pub id: String,
    pub name: Option<String>,
    pub api: String,
    pub context_window: Option<u32>,
    pub max_tokens: Option<u32>,
    /// Dollars per million tokens.
    pub cost: Option<Cost>,
    #[serde(default)]
    pub reasoning: bool,
    #[serde(default)]
    pub input: Vec<String>,
    pub thinking: Option<ThinkingRow>,
    pub compat: Option<CompletionsCompat>,
    pub anthropic_compat: Option<AnthropicQuirks>,
}

/// Disable modes the Chat Completions wire implements; a reasoning row with any other mode is
/// treated as a non-reasoning model in v1.
fn disable_mode_supported(mode: Option<&str>) -> bool {
    matches!(mode, None | Some("omit" | "lowest-effort" | "none-effort"))
}

impl Row {
    /// The model as a natively routed one. `None` when the row's api is not one mu speaks.
    pub fn spec(&self, provider: &str, default_window: u32, default_max: u32) -> Option<ModelSpec> {
        let api = Api::parse(&self.api)?;
        let compat = (api == Api::OpenAiCompletions).then(|| self.compat.clone().unwrap_or_default());
        let mode = match (&self.thinking, self.reasoning) {
            (Some(t), true) => ThinkingMode::parse(&t.mode),
            _ => ThinkingMode::None,
        };
        let mode = match &compat {
            Some(c) if !disable_mode_supported(c.reasoning_disable_mode.as_deref()) => ThinkingMode::None,
            _ => mode,
        };
        let strip = compat.as_ref().is_some_and(|c| c.strip_image_input);
        Some(ModelSpec {
            id: format!("{provider}/{}", self.id),
            provider: provider.into(),
            context_window: self.context_window.unwrap_or(default_window),
            max_output: self.max_tokens.unwrap_or(default_max),
            api,
            native: true,
            wire_id: self.id.clone(),
            thinking: ThinkingSpec {
                mode,
                efforts: if mode == ThinkingMode::None {
                    Vec::new()
                } else {
                    self.thinking.as_ref().map(|t| t.efforts.clone()).unwrap_or_default()
                },
            },
            images: self.input.iter().any(|i| i == "image") && !strip,
            compat,
            anthropic: if api == Api::AnthropicMessages {
                AnthropicQuirks {
                    supports_display: self.thinking.as_ref().and_then(|t| t.supports_display),
                    ..self.anthropic_compat.clone().unwrap_or_default()
                }
            } else {
                AnthropicQuirks::default()
            },
        })
    }
}

fn all() -> &'static HashMap<String, Vec<Row>> {
    static ALL: OnceLock<HashMap<String, Vec<Row>>> = OnceLock::new();
    ALL.get_or_init(|| serde_json::from_str(SNAPSHOT).expect("crates/mu-provider/src/model/catalog.json is valid"))
}

/// The provider's rows, sorted by id; empty for a provider the snapshot does not cover.
pub fn rows(provider: &str) -> &'static [Row] {
    // The ChatGPT plan serves the API's models, so it reads their rows.
    let provider = if provider == crate::auth::chatgpt::PROVIDER_ID { "openai" } else { provider };
    all().get(provider).map_or(&[], Vec::as_slice)
}

pub fn row(provider: &str, id: &str) -> Option<&'static Row> {
    rows(provider).iter().find(|r| r.id == id)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn snapshot_parses_and_covers_the_three_providers() {
        for p in ["anthropic", "openai", "baseten"] {
            assert!(!rows(p).is_empty(), "{p}");
        }
        for r in rows("anthropic") {
            assert_eq!(r.api, "anthropic-messages", "{}", r.id);
        }
        assert!(rows("baseten").iter().all(|r| r.api == "openai-completions" && r.compat.is_some()));
    }

    #[test]
    fn rows_become_native_specs() {
        let r = row("anthropic", "claude-sonnet-5-5").unwrap();
        let s = r.spec("anthropic", 1, 1).unwrap();
        assert_eq!(
            (s.api, s.native, s.wire_id.as_str(), s.id.as_str()),
            (Api::AnthropicMessages, true, "claude-sonnet-5-5", "anthropic/claude-sonnet-5-5")
        );
        assert_eq!(s.thinking.mode, ThinkingMode::AnthropicAdaptive);
        assert!(s.images && s.context_window > 1 && s.max_output > 1);

        let k = row("baseten", "moonshotai/Kimi-K3").unwrap().spec("baseten", 1, 1).unwrap();
        assert_eq!(k.api, Api::OpenAiCompletions);
        assert_eq!(k.thinking.mode, ThinkingMode::Effort);
        let c = k.compat.unwrap();
        assert!(c.requires_reasoning_content_for_tool_calls);
        assert_eq!(c.reasoning_content_field.as_deref(), Some("reasoning_content"));
    }

    #[test]
    fn unsupported_disable_mode_means_no_reasoning() {
        let mut r = row("baseten", "moonshotai/Kimi-K3").unwrap().clone();
        r.compat.as_mut().unwrap().reasoning_disable_mode = Some("budget-zero".into());
        let s = r.spec("baseten", 1, 1).unwrap();
        assert_eq!((s.thinking.mode, s.thinking.efforts.is_empty()), (ThinkingMode::None, true));
    }
}
